module top_module(
  input wire clk,            // Added clock input
  input wire [7:0] pos_cmd,
  input wire [7:0] fb,
  output reg pwm_out         // Changed from wire to reg for pwm_out
);parameter pwm_period = 20; // PWM period in clock cycles (adjusted to integer)
parameter pos_resolution = 1; // Position resolution in degrees
parameter kp = 1; // Proportional gain, changed to integer
parameter ki = 1; // Integral gain, changed to integer

reg [7:0] error;
reg [7:0] integral;
reg [7:0] duty_cycle;
reg [7:0] pwm_count;

always @(posedge clk) begin
  // Calculate the error between the position command and the feedback signal
  error <= pos_cmd - fb;

  // Update the integral of the error
  integral <= integral + error;

  // Calculate the duty cycle based on the proportional and integral gains
  duty_cycle <= (kp * error) + (ki * integral);

  // Limit the duty cycle to the range [0, 255]
  if (duty_cycle > 255) begin
    duty_cycle <= 255;
  end else if (duty_cycle < 0) begin
    duty_cycle <= 0;
  end

  // Update the PWM count
  pwm_count <= pwm_count + 1;

  // Generate the PWM signal based on the duty cycle and PWM period
  if (pwm_count < (duty_cycle * pwm_period) / 256) begin // Adjusted calculation
    pwm_out <= 1;
  end else begin
    pwm_out <= 0;
  end

  // Reset the PWM count when it reaches the maximum value
  if (pwm_count == 255) begin
    pwm_count <= 0;
  end
end

endmodule

