 if((WB_RegWrite)&&(WBRegRd != 0)&&(WBRegRd == EXRegRt)&&(MEMRegRd != EXRegRt) )
 ForwardB = 2'b01;
 else if((MEM_RegWrite)&&(MEMRegRd != 0)&&(MEMRegRd == EXRegRt))
 ForwardB = 2'b10;
 else
 ForwardB = 2'b00;
 end
endmodule

