module traffic_light (
    input clk,
    input areset,
    output reg [1:0] ns_light,  // North-South light: 2'b00=Red, 2'b01=Yellow, 2'b10=Green
    output reg [1:0] ew_light   // East-West light: 2'b00=Red, 2'b01=Yellow, 2'b10=Green
);parameter NS_GREEN = 0, NS_YELLOW = 1, EW_GREEN = 2, EW_YELLOW = 3;
    reg [1:0] state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= NS_GREEN;
        else
            state <= next_state;
    end

    always_comb begin
        case (state)
            NS_GREEN: next_state = NS_YELLOW;
            NS_YELLOW: next_state = EW_GREEN;
            EW_GREEN: next_state = EW_YELLOW;
            EW_YELLOW: next_state = NS_GREEN;
            default: next_state = NS_GREEN;
        endcase
    end

    always_comb begin
        case (state)
            NS_GREEN: begin
                ns_light = 2'b10;
                ew_light = 2'b00;
            end
            NS_YELLOW: begin
                ns_light = 2'b01;
                ew_light = 2'b00;
            end
            EW_GREEN: begin
                ns_light = 2'b00;
                ew_light = 2'b10;
            end
            EW_YELLOW: begin
                ns_light = 2'b00;
                ew_light = 2'b01;
            end
            default: begin
                ns_light = 2'b10;
                ew_light = 2'b00;
            end
        endcase
    end

endmodule

