description:
Design a clock generator module that divides an input clock frequency by a specified parameter (DIVIDER). The module takes an input clock signal and a reset signal, and produces an output clock signal that toggles at a rate determined by the input clock frequency divided by the specified DIVIDER value. When reset is activated, the output clock and internal counter are reset to ensure predictable behavior. This module can be used in applications requiring clock signal manipulation to create slower clock frequencies for various digital circuits.
module top_module(
    input clk_in1,
    input reset,
    output clk_out1
);

code:
module top_module(
    input clk_in1,
    input reset,
    output clk_out1
);parameter DIVIDER = 4; // Change this to 2, 4, 8, 16 for different clock frequencies
reg [31:0] counter = 0;
reg clk_out1_reg = 0;

always @(posedge clk_in1, posedge reset) begin
    if (reset) begin
        counter <= 0;
        clk_out1_reg <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == (clk_in1 / DIVIDER) - 1) begin
            counter <= 0;
            clk_out1_reg <= ~clk_out1_reg;
        end
    end
end

assign clk_out1 = clk_out1_reg;

endmodule

