description:
Design a system reset module that generates a system active-low reset signal (`sys_rst_n`) and a clock signal for an ADC (`clk_adc`). The module counts clock cycles to determine when to assert the reset after a specified delay of 50,000 cycles. It also produces a 1-bit ADC clock that toggles at a frequency determined by `CLKADC_PARA`, specifically set to a ratio of the system clock. The reset signal holds its asserted state for one clock cycle and is de-asserted afterward, while the ADC clock is low for a brief duration defined by `CLKADC_PARA_2` before returning high for the remainder of the cycle.
module top_module(
    input    clk,

    output    sys_rst_n,
	 output	  clk_adc
);

code:
module top_module(
    input    clk,

    output    sys_rst_n,
	 output	  clk_adc
);localparam	CLKADC_PARA = 10;	
localparam 	CLKADC_PARA_2 = 5;


reg[22:0] cnt;
reg[9:0]  cnt_adc = 0;
reg clk_adc_r;
always@(posedge clk) 

begin




			if(cnt < 23'd50_0000) 
            cnt <= cnt+1'b1;
			else if(cnt == 23'd50_0000)
            cnt <= cnt;
			else cnt <= 0;

		 if(cnt_adc < CLKADC_PARA-1) cnt_adc <= cnt_adc + 1'b1;
		 else cnt_adc <= 10'd0;
end



reg    rst_nr0 = 0;
reg    rst_nr1 = 0;
always@(posedge clk)

begin






	if(cnt == 23'd50_0000)
        begin
        rst_nr0 <= 1;
        rst_nr1 <= rst_nr0;
        end
    else
        begin
        rst_nr0 <= 0;
        rst_nr1 <= 0;
        end
	if(cnt_adc < CLKADC_PARA_2) clk_adc_r <= 1'b0;
	else
	clk_adc_r <= 1'b1;
end

assign    sys_rst_n = rst_nr1;
assign    clk_adc = clk_adc_r;
endmodule

