description:
Design a debouncer circuit for a mechanical switch input to ensure stable output during toggling. The module monitors the switch state and implements a state machine that transitions through three states: waiting for switch stabilization, waiting for the debounce period, and outputting the debounced signal. It uses a timer to filter out fluctuations, only updating the output after the switch state has been stable for a defined duration based on the clock period. This prevents erroneous signals caused by switch bounce, providing a clean, reliable output signal.
module top_module(
  input clk,        // Added clock input
  input sw,
  output reg deb    // Changed output to reg
);

code:
module top_module(
  input clk,        // Added clock input
  input sw,
  output reg deb    // Changed output to reg
);parameter clk_period = 10; // clock period in ns.

reg [1:0] state;
reg debounced;
reg [31:0] debounce_timer;

always @(posedge clk) begin
  case (state)
    2'b00: begin // waiting for switch to stabilize
      debounce_timer <= debounce_timer + 1;
      if (sw != debounced) begin
        debounce_timer <= 0;
        state <= 2'b01;
      end
    end
    2'b01: begin // waiting for debounce time
      debounce_timer <= debounce_timer + 1;
      if (debounce_timer >= (10 * clk_period)) begin
        debounced <= sw;
        state <= 2'b10;
      end
    end
    2'b10: begin // output debounced signal
      deb <= debounced;  // deb can be assigned here since it's a reg
      if (sw != debounced) begin
        debounce_timer <= 0;
        state <= 2'b01;
      end
    end
  endcase
end

endmodule

