    input [3:0] A,
    input clk,         // Added clk input
    output [15:0] Y
);reg [15:0] Y_reg;
reg [3:0] A_reg;

always @(posedge clk) begin
    A_reg <= A;
    Y_reg <= 16'b0;
    case (A_reg)
        4'b0000: Y_reg[15] <= 1'b1; // Changed from 0 to 1 to properly output high for decoded values
