description:
Design a Power-On Reset (PORRST) circuit that outputs a negative reset signal (porrst_n). In FPGA implementations, this signal is always HIGH (inactive), while in other configurations, the circuit generates the reset signal by using a counter. During the first 100 clock cycles, porrst_n is LOW (active), indicating that the system is in reset state, and after reaching this threshold, the porrst_n signal transitions to HIGH (inactive), allowing normal operation.
module top_module(
  output reg porrst_n,  // Change to reg because it is driven in an always block
  input clk              // Declare clk input to fix the binding error
);

code:
module top_module(
  output reg porrst_n,  // Change to reg because it is driven in an always block
  input clk              // Declare clk input to fix the binding error
);`ifdef FPGA_SOURCE
      // In FPGA, we have no PORRST circuit
      assign porrst_n = 1'b1;
  `else
      // Generate PORRST signal using circuit
      reg [31:0] counter = 0;
      always @(posedge clk) begin
        if (counter < 100) begin
          counter <= counter + 1;
          porrst_n <= 1'b0;
        end else begin
          porrst_n <= 1'b1;
        end
      end
  `endif

endmodule

