description:
Implement a circuit that converts a 4-bit binary input into its corresponding 4-bit Gray code output. The conversion is achieved through combinational logic, where each bit of the Gray code is derived from specific bitwise XOR operations on the binary input. Additionally, the output is updated synchronously on the rising edge of the clock signal, enabling stable output synchronization with the clock.
module top_module(
    input [3:0] bin_in,
    input clk,
    output reg [3:0] gray_out
);

code:
module top_module(
    input [3:0] bin_in,
    input clk,
    output reg [3:0] gray_out
);// Combinational logic block for binary to gray code conversion
    always @* begin
        gray_out[0] = bin_in[0] ^ bin_in[1];
        gray_out[1] = bin_in[1] ^ bin_in[2];
        gray_out[2] = bin_in[2] ^ bin_in[3];
        gray_out[3] = bin_in[3];
    end

    // Edge-triggered flip-flop for storing the output value
    always @(posedge clk) begin
        gray_out <= gray_out;
    end

endmodule

