      4'b0001: F = 1'b1;
      4'b0010: F = 1'b0;
      4'b0011: F = 1'b1;
      4'b0110: F = 1'b1;
      4'b0111: F = 1'b0;
      4'b1110: F = 1'b1;
      4'b1111: F = 1'b0;
      default: F = 1'b0;
    endcase
  end

endmodule

