module top_module(
					clk,
					nRst,
					ws,		
					bck		
					);input	clk;
input	nRst;
output	ws;
output	bck;

parameter	CNT_WS_WIDTH = 6;				
parameter	CNT_BCK_WIDTH = 11;
parameter	DIV_VALUE = 12;



reg	[4:0] cnt_ws;
reg	[3:0]	cnt_bck;
reg	bck_reg;
reg	ws_reg;



always@(posedge clk or negedge nRst)
begin
	if(!nRst)
	begin
		cnt_bck <= 4'b0000;
		cnt_ws  <= 5'b0_0000;
		bck_reg	<= 1'b0;
		ws_reg <= 1'b1;
	end
	else 
	begin
		if(cnt_bck < 4'b0111)
			cnt_bck[3:0] <= cnt_bck[3:0] + 4'b0001;
		else
		begin
			cnt_bck <= 4'b0000;
			bck_reg <= ~bck_reg;
			if(bck_reg == 1'b1)
			begin
				if(cnt_ws < 5'b0_1111)	
					cnt_ws[4:0] <= cnt_ws[4:0] + 5'b0_0001;
				else
				begin
					cnt_ws <= 5'b0_0000;
					ws_reg <= ~ws_reg;
				end
			end
		end

	end


end



assign ws = ws_reg;		
assign bck = bck_reg;	

endmodule

module top_module(input[31:0] op1,
		input[31:0] op2,
		input[3:0] f,
		output reg[31:0] result,
		output zero);always @(op1, op2, f)
		case (f)
			0: result = op1 + op2;
            1: result = op1 - op2;
            2: result = op1 & op2;
            3: result = op1 | op2;
            4: result = op1 ~| op2;
            5: result = op1 ^ op2;
            6: result = op1 << op2;
            7: result = op1 >> op2;
            8: result = op1 >>> op2;
            9: result = ($signed(op1) < $signed(op2)) ? 1 : 0; 
            10: result = (op1 < op2) ? 1 : 0;   

        endcase 

	assign zero = result == 0;
endmodule

