    always @(posedge i_clk or negedge i_rst_n) begin
        if (~i_rst_n) begin
            add_val[31:0] <= 32'd0;
        end else begin
            add_val[31:0] <= i_addr[31:0];
        end
    end


    always @(posedge i_clk or negedge i_rst_n) begin
        if (~i_rst_n) begin
            acc[31:0] <= 32'd0;
        end else if (~i_en) begin
            acc[31:0] <= 32'd0;
        end else begin
            acc[31:0] <= acc[31:0] + add_val[31:0];
        end
    end

    assign o_sig = acc[31];

