description:
Implement the Verilog module based on the following description.
Module M implements the boolean function z = x & y.

// Module N can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 1.
If x = 0, y = 1, then z = 0.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 0.

// Now consider a top-level that uses two M submodules and two N submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first M submodule is connected to a two-input OR, along with the output of the first N submodule. The second pair of M and N submodules is similarly connected to an XOR gate. The output of the OR and the XOR is connected to an AND, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output z);

code:
module M(
    input x,
    input y,
    output z
);
    assign z = x & y;
endmodule

module N(
    input x,
    input y,
    output z
);
    assign z = x & y;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire m1_out, m2_out, n1_out, n2_out;
    wire or_out, xor_out;

    M m1(.x(x), .y(y), .z(m1_out));
    M m2(.x(x), .y(y), .z(m2_out));
    N n1(.x(x), .y(y), .z(n1_out));
    N n2(.x(x), .y(y), .z(n2_out));

    assign or_out = m1_out | n1_out;
    assign xor_out = m2_out ^ n2_out;

    assign z = or_out & xor_out;
endmodule

