module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    input select, // Select input to choose between register and D flip-flops
    output [7:0] q, // 8-bit output from the active module
    output done // Signal indicating when all D flip-flops have finished loading their initial values
);// 8-bit register with active high asynchronous reset
    reg [7:0] reg_out;
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // 8 D flip-flops with active high asynchronous reset
    reg [7:0] dff_out [0:7];
    integer i;
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 8; i = i + 1) begin
                dff_out[i] <= 8'h34;
            end
        end else begin
            for (i = 0; i < 8; i = i + 1) begin
                dff_out[i] <= select ? dff_out[i] : d[i];
            end
        end
    end

    // 9th D flip-flop triggered by negative edge of clk
    reg done_out;
    reg [7:0] or_out;
    always @ (negedge clk or posedge reset) begin
        if (reset) begin
            done_out <= 1'b0;
            or_out <= 8'h00;
        end else begin
            done_out <= 1'b1;
            for (i = 0; i < 8; i = i + 1) begin
                or_out[i] <= reg_out[i] | dff_out[i];
                done_out <= done_out & (dff_out[i] != 8'h34);
            end
        end
    end

    // Output the final result based on select input
    assign q = select ? reg_out : or_out;
    assign done = done_out;

endmodule

