module fsm (
	input clk,
	input reset,
	input x,
	input y,
	output reg n);

	parameter P=0, Q=1, S1=2, S2=3, S3=4, S4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= P;
		else state <= next;
	end

	always_comb begin
		case (state)
			P: next = x ? Q : P;
			Q: next = y ? S1 : S2;
			S1: next = y ? S2 : S3;
			S2: next = y ? S3 : S4;
			S3: next = y ? S4 : P;
			S4: next = x ? Q : P;
			default: next = 'x;
		endcase
	end

	assign n = (state == S1);

endmodule

