module fsm_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg reset;
    reg x;
    reg y;
    wire n;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    fsm dut (
        .clk(clk),
        .reset(reset),
        .x(x),
        .y(y),
        .n(n)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            x = 0;
            y = 0;
            @(posedge clk);
            #1;
            reset = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Success - y=1 on first cycle of window", test_num);
            reset_dut();
            x = 1;
            @(posedge clk); #1;
            y = 1;
            @(posedge clk); #1;
            y = 0;
            @(posedge clk); #1;
            @(posedge clk); #1;
            @(posedge clk); #1;

            #1;


            check_outputs(1'b1);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Success - y=1 on fourth cycle of window", test_num);
            reset_dut();
            x = 1;
            @(posedge clk); #1;
            y = 0;
            repeat(3) @(posedge clk); #1;
            y = 1;
            @(posedge clk); #1;
            #1;

            check_outputs(1'b1);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Failure - y=0 throughout window", test_num);
            reset_dut();
            x = 1;
            @(posedge clk); #1;
            y = 0;
            repeat(4) @(posedge clk); #1;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Override - x returns to 0 during window", test_num);
            reset_dut();
            x = 1;
            @(posedge clk); #1;
            y = 1;
            @(posedge clk); #1;
            x = 0;
            @(posedge clk); #1;
            @(posedge clk); #1;
            @(posedge clk); #1;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Re-triggering - sequence after completion", test_num);
            reset_dut();

            x = 1; @(posedge clk); #1;
            y = 1; @(posedge clk); #1;
            repeat(3) @(posedge clk); #1;

            x = 1;
            @(posedge clk); #1;
            y = 0;
            repeat(4) @(posedge clk); #1;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Synchronous Reset during window", test_num);
            reset_dut();
            x = 1;
            @(posedge clk); #1;
            y = 1;
            @(posedge clk); #1;
            reset = 1;
            @(posedge clk); #1;
            reset = 0;
            repeat(2) @(posedge clk); #1;
            #1;

            check_outputs(1'b0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("fsm Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_n;
        begin
            if (expected_n === (expected_n ^ n ^ expected_n)) begin
                $display("PASS");
                $display("  Outputs: n=%b",
                         n);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: n=%b",
                         expected_n);
                $display("  Got:      n=%b",
                         n);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, reset, x, y, n);
    end

endmodule

